package com.enterprise.licensing.engine.cache;
import static org.assertj.core.api.Assertions.assertThat;import com.enterprise.licensing.crypto.*;import com.enterprise.licensing.crypto.runtime.*;import com.enterprise.licensing.engine.activation.*;import com.enterprise.licensing.engine.identity.*;import com.enterprise.licensing.engine.instance.*;import com.enterprise.licensing.engine.validation.LicenseValidationResult;import com.enterprise.licensing.model.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;import java.security.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class CachedEntitlementServiceTest{
 @Test void signsBindsAndCapsCertificateWhileTamperingFails(){var mapper=new ObjectMapper().registerModule(new JavaTimeModule());var canonical=new CanonicalJson(mapper);var key=Ed25519Keys.generate();var now=Instant.parse("2026-01-01T00:00:00Z");var identity=new LicenseServerIdentity(UUID.randomUUID(),new EncodedPublicKey("Ed25519","X.509",Ed25519Keys.encodePublic(key.getPublic())),Ed25519Keys.fingerprint(key.getPublic()),now,Map.of());var identityService=new LicenseServerIdentityService(()->new IdentityMaterial(identity,key.getPublic(),key.getPrivate()));var license=license(now.plus(Duration.ofHours(2)));var instance=new RegisteredProductInstance("i",new EncodedPublicKey("Ed25519","X.509",Ed25519Keys.encodePublic(key.getPublic())),Ed25519Keys.fingerprint(key.getPublic()),ProductId.VALIDATOR,DeploymentType.TOMCAT,EnvironmentType.PRODUCTION,"1",InstanceState.ACTIVE,now,now,null,Map.of());var service=new CachedEntitlementService(new FixedLicenseRepository(license),new FixedInstanceRepository(instance),identityService,new MemoryCache(),()->now,()->UUID.randomUUID(),Duration.ofHours(24),canonical,ignored->LicenseValidationResult.allowed(false));var issued=service.issue("i");assertThat(issued.accepted()).isTrue();assertThat(issued.certificate().expiresAt()).isEqualTo(license.subscription().graceUntil());assertThat(issued.certificate().products()).singleElement().extracting(ProductEntitlement::id).isEqualTo(ProductId.VALIDATOR);var verifier=new CachedEntitlementVerifier(new RuntimeEnvelopeVerifier(canonical,Set.of("1.0")),new EnvelopeJsonCodec(mapper));assertThat(verifier.verify(issued.envelope(),key.getPublic(),identity.licenseServerId().toString(),"i",instance.publicKeyFingerprint(),now).valid()).isTrue();var e=issued.envelope();var changed=new SignedEnvelope(e.envelopeVersion(),e.artifactType(),e.payloadSchemaVersion(),e.algorithm(),e.keyId(),e.payload(),(e.signature().charAt(0)=='A'?"B":"A")+e.signature().substring(1));assertThat(verifier.verify(changed,key.getPublic(),identity.licenseServerId().toString(),"i",instance.publicKeyFingerprint(),now).reasonCode()).isEqualTo(LicenseReasonCode.LICENSE_SIGNATURE_INVALID);}
 @Test void refusesCacheForEveryInactiveInstanceState(){var mapper=new ObjectMapper().registerModule(new JavaTimeModule());var key=Ed25519Keys.generate();var now=Instant.parse("2026-01-01T00:00:00Z");var identity=new LicenseServerIdentity(UUID.randomUUID(),new EncodedPublicKey("Ed25519","X.509",Ed25519Keys.encodePublic(key.getPublic())),Ed25519Keys.fingerprint(key.getPublic()),now,Map.of());for(var state:List.of(InstanceState.REGISTERED,InstanceState.STANDBY,InstanceState.DECOMMISSIONED)){var instance=new RegisteredProductInstance("i",identity.publicKey(),identity.publicKeyFingerprint(),ProductId.VALIDATOR,DeploymentType.TOMCAT,EnvironmentType.PRODUCTION,"1",state,now,now,state==InstanceState.DECOMMISSIONED?now:null,Map.of());var service=new CachedEntitlementService(new FixedLicenseRepository(license(now.plusSeconds(60))),new FixedInstanceRepository(instance),new LicenseServerIdentityService(()->new IdentityMaterial(identity,key.getPublic(),key.getPrivate())),new MemoryCache(),()->now,()->UUID.randomUUID(),Duration.ofHours(1),new CanonicalJson(mapper),ignored->LicenseValidationResult.allowed(false));assertThat(service.issue("i").reasonCode()).isEqualTo(LicenseReasonCode.INSTANCE_NOT_REGISTERED);}}
 private static CommercialLicense license(Instant end){return new CommercialLicense("1.0","L",new CustomerIdentity("C","Customer","c@x"),new SubscriptionEntitlement("SUBSCRIPTION","T",Instant.parse("2025-01-01T00:00:00Z"),end,0),new ActivationPolicy(true,1,true),List.of(new EnvironmentEntitlement(EnvironmentType.PRODUCTION,1,false)),new UserEntitlement(1,1,List.of()),List.of(new ProductEntitlement(ProductId.VALIDATOR,true,1,Set.of(new FeatureId("TABLEAU"))),new ProductEntitlement(new ProductId("DATA_MANAGER"),true,1,Set.of(new FeatureId("EXPORT")))),new AIEntitlement(false,0,0,Set.of(),List.of()),1,Set.of());}
 private record FixedLicenseRepository(CommercialLicense value)implements LicenseRepository{public void activate(LicenseServerIdentity i,CommercialLicense l,SignedEnvelope le,ActivationCertificate a,SignedEnvelope ae,Instant at){}public Optional<ActiveLicenseState>active(){return Optional.of(new ActiveLicenseState(value,null,null,null,Instant.EPOCH));}public boolean isRevoked(String t,String i,Instant a){return false;}}
 private record FixedInstanceRepository(RegisteredProductInstance value)implements ProductInstanceRepository{public InstanceRegistrationResult register(InstanceRegistrationRequest r,String f,int e,int a,Instant n){throw new UnsupportedOperationException();}public Optional<RegisteredProductInstance>find(String id){return value.instanceId().equals(id)?Optional.of(value):Optional.empty();}public List<RegisteredProductInstance>list(){return List.of(value);}public InstanceRegistrationResult transition(String i,InstanceState e,InstanceState t,int l,Instant n,boolean f){throw new UnsupportedOperationException();}}
 private static final class MemoryCache implements CachedEntitlementRepository{SignedEnvelope envelope;public void save(CachedEntitlementCertificate c,SignedEnvelope e){envelope=e;}public Optional<SignedEnvelope>latestFor(String i){return Optional.ofNullable(envelope);}public void revokeFor(String i,Instant a){envelope=null;}}
}
